// Everything a person checks before an invoice is allowed into the ledger.
// Nothing here calls an API. It compares what the model read off the PDF
// against the Xero contacts, the open purchase orders and the bills already
// posted, then says post it, hold it for a person, or send it back.

const inv = $('Read the invoice').first().json.output || $('Read the invoice').first().json;

const contacts = $('Suppliers in Xero').all().map(i => i.json);
const posted   = $('Bills already in Xero').all().map(i => i.json);

// The purchase orders come back from the Xero API in one of two shapes: one
// item holding a PurchaseOrders array, or one item per order when n8n splits
// the response. Reading only the first item, as an earlier version did, meant
// every invoice quoting any order but the first was rejected as not open.
const orders = $('Open purchase orders').all().map(i => i.json).reduce(function (acc, r) {
  if (r && Array.isArray(r.PurchaseOrders)) return acc.concat(r.PurchaseOrders);
  if (r && r.PurchaseOrderNumber) return acc.concat([r]);
  return acc;
}, []);

// ---- tunables ---------------------------------------------------------------
const ROUNDING_TOLERANCE = 0.02;   // currency units allowed on subtotal + tax = total
const PO_TOLERANCE_PCT   = 2;      // percent an invoice may exceed the purchase order
const MAX_AGE_DAYS       = 120;    // older than this is almost always a re-submission
const APPROVAL_LIMIT     = 10000;  // above this a person signs it off even when clean
const VALID_TAX_RATES    = [0, 5, 20];  // set these to your own jurisdiction
// -----------------------------------------------------------------------------

const norm = s => String(s == null ? '' : s).toLowerCase()
  .replace(/\b(ltd|limited|llc|l\.l\.c|plc|llp|inc|co|company|fzco|fze|fzc|est|establishment)\b/g, '')
  .replace(/[^a-z0-9]/g, '').trim();

const num = v => {
  const s = String(v == null ? '' : v).replace(/[^0-9.\-]/g, '');
  if (s === '' || s === '-' || s === '.') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const days = d => { const t = Date.parse(d); return Number.isFinite(t) ? Math.round((Date.now() - t) / 86400000) : null; };

const failures = [];
const warnings = [];

// 1. Did the model actually read the document. A missing field is never guessed.
for (const f of ['supplier', 'invoice_number', 'total']) {
  if (inv[f] == null || String(inv[f]).trim() === '') failures.push('could not read the ' + f.replace('_', ' ') + ' from the PDF');
}

const total    = num(inv.total);
const subtotal = num(inv.subtotal);
const tax      = num(inv.tax_amount);

// 2. A field that is present but is not a number is worse than a missing one,
// because every arithmetic check below silently skips it and the invoice sails
// through. An amount that will not parse stops the invoice here.
[['total', inv.total, total], ['subtotal', inv.subtotal, subtotal], ['tax amount', inv.tax_amount, tax]].forEach(function (row) {
  const label = row[0], raw = row[1], parsed = row[2];
  if (raw != null && String(raw).trim() !== '' && parsed === null) {
    failures.push('the ' + label + ' reads "' + raw + '", which is not an amount');
  }
});

// 3. Is this supplier one of ours, and are they still active in Xero.
// A loose name match is how an invoice ends up posted against the wrong
// contact, so a near match is only accepted when it is the ONLY one.
const supplierKey = norm(inv.supplier);
let contact = null;
let supplierRuled = false;

if (supplierKey) {
  const exact = contacts.filter(c => norm(c.Name) === supplierKey);
  if (exact.length === 1) {
    contact = exact[0];
  } else if (exact.length > 1) {
    failures.push('supplier "' + inv.supplier + '" matches ' + exact.length + ' contacts in Xero, so a person picks the right one');
    supplierRuled = true;
  } else if (supplierKey.length >= 5) {
    const near = contacts.filter(function (c) {
      const k = norm(c.Name);
      return k.length >= 5 && (k.indexOf(supplierKey) !== -1 || supplierKey.indexOf(k) !== -1);
    });
    if (near.length === 1) {
      contact = near[0];
      warnings.push('supplier matched on a near name: "' + inv.supplier + '" against "' + near[0].Name + '"');
    } else if (near.length > 1) {
      failures.push('supplier "' + inv.supplier + '" is close to ' + near.length + ' contacts in Xero, so a person picks the right one');
      supplierRuled = true;
    }
  }
}

if (!contact) {
  if (!supplierRuled) failures.push('supplier "' + (inv.supplier == null ? '' : inv.supplier) + '" is not a contact in Xero');
} else {
  if (String(contact.ContactStatus || '').toUpperCase() === 'ARCHIVED') {
    failures.push('supplier "' + contact.Name + '" is archived in Xero');
  }
  // 4. Tax number. A changed tax number is the classic redirected payment fraud.
  const onFile = String(contact.TaxNumber || '').replace(/\D/g, '');
  const onDoc  = String(inv.supplier_tax_number || '').replace(/\D/g, '');
  if (onFile && onDoc && onFile !== onDoc) {
    failures.push('tax number on the invoice (' + onDoc + ') does not match the one on the Xero contact (' + onFile + ')');
  } else if (onFile && !onDoc) {
    warnings.push('no tax number on the invoice, one is held in Xero');
  }
}

// 5. Have we already posted this exact bill.
const dup = posted.find(b =>
  String(b.InvoiceNumber || '').trim().toLowerCase() === String(inv.invoice_number || '').trim().toLowerCase() &&
  norm((b.Contact || {}).Name) === supplierKey);
if (dup) failures.push('invoice ' + inv.invoice_number + ' is already in Xero as ' + (dup.InvoiceID || 'an existing bill'));

// 6. Does the invoice add up. This is arithmetic, not opinion.
if (total != null && subtotal != null && tax != null) {
  if (Math.abs((subtotal + tax) - total) > ROUNDING_TOLERANCE) {
    failures.push('subtotal ' + subtotal + ' plus tax ' + tax + ' is ' + (subtotal + tax).toFixed(2) + ', not the stated total ' + total);
  }
  if (subtotal > 0) {
    const rate = Math.round((tax / subtotal) * 1000) / 10;
    if (!VALID_TAX_RATES.some(r => Math.abs(rate - r) < 0.6)) {
      warnings.push('tax works out at ' + rate + ' percent, which is not a rate we expect');
    }
  }
}

// 7. What actually goes on the Xero line. Xero wants the tax exclusive figure,
// so a bill can only be posted when that figure is known. Posting the total by
// mistake overstates the cost by the tax; posting nothing creates a bill for
// zero that looks paid. Neither is allowed to happen quietly.
let net = subtotal;
if (net === null && total !== null && (tax === null || tax === 0)) net = total;
if (net === null) {
  failures.push('the tax exclusive amount cannot be worked out, so there is nothing safe to put on the bill');
}

// 8. Match the purchase order, if one is quoted.
let matchedPo = null;
if (inv.po_number) {
  matchedPo = orders.find(o => String(o.PurchaseOrderNumber || '').trim().toLowerCase() === String(inv.po_number).trim().toLowerCase());
  if (!matchedPo) {
    failures.push('purchase order ' + inv.po_number + ' is not open in Xero');
  } else {
    const poTotal = num(matchedPo.Total);
    if (poTotal != null && total != null && poTotal > 0) {
      const over = ((total - poTotal) / poTotal) * 100;
      if (over > PO_TOLERANCE_PCT) {
        failures.push('invoice is ' + over.toFixed(1) + ' percent above purchase order ' + inv.po_number + ' (' + total + ' against ' + poTotal + ')');
      }
    }
    const poSupplier = norm((matchedPo.Contact || {}).Name);
    if (poSupplier && supplierKey && poSupplier !== supplierKey) {
      failures.push('purchase order ' + inv.po_number + ' belongs to ' + (matchedPo.Contact || {}).Name + ', not ' + inv.supplier);
    }
  }
} else {
  warnings.push('no purchase order quoted on the invoice');
}

// 9. The date. A date the ledger cannot use is a failure, not a warning: Xero
// would either refuse the bill or quietly stamp it with today, which puts the
// cost in the wrong period and moves the payment run.
const age = days(inv.issue_date);
if (inv.issue_date == null || String(inv.issue_date).trim() === '') {
  failures.push('no issue date could be read, so the bill would land in the wrong period');
} else if (age === null) {
  failures.push('the issue date reads "' + inv.issue_date + '", which is not a date');
} else if (age < -1) {
  failures.push('the invoice is dated ' + inv.issue_date + ', which is in the future');
} else if (age > MAX_AGE_DAYS) {
  failures.push('invoice is dated ' + inv.issue_date + ', which is ' + age + ' days ago');
}

// 10. Value. Above the limit a person signs it off however clean it looks.
const overLimit = total != null && Math.abs(total) > APPROVAL_LIMIT;

// A credit note is negative by design and must never be posted as a bill.
const isCredit = total != null && total < 0;

let decision;
if (failures.length)      decision = 'reject';
else if (isCredit)        decision = 'approve';
else if (overLimit)       decision = 'approve';
else                      decision = 'post';

const reason = failures.length ? failures[0]
  : isCredit ? 'this is a credit note, so a person posts it against the right bill'
  : overLimit ? 'above the approval limit of ' + APPROVAL_LIMIT
  : 'passed every check';

return [{
  json: {
    decision,
    reason,
    failures,
    warnings,
    supplier: inv.supplier || '',
    supplier_email: (contact || {}).EmailAddress || '',
    contact_id: (contact || {}).ContactID || '',
    invoice_number: inv.invoice_number || '',
    po_number: inv.po_number || '',
    issue_date: inv.issue_date || '',
    due_date: inv.due_date || '',
    currency: inv.currency || '',
    subtotal, tax_amount: tax, total, net,
    line_items: inv.line_items || [],
    checked_at: new Date().toISOString(),
  },
}];

